import {TRAIT_GUIDE,traitLevelText} from './trait-guide.js';
import {illustrationPrompt,isArtworkData} from './illustration.js';
import {STEPS,ATTR,SKILLS,PROFILES,DISC,CLANS,CLAN_GUIDE,POWERS,RITUALS,TRAITS,SPECIAL,CEREMONIES} from './data.js';
import {blank,derived,budget,score,errors,importJSON,traitIssue,powerAllowed,normalizePowers,disciplineIds,effectiveSkills,allTraits,predatorErrors,baseScore} from './engine.js';
import {PREDATORS,OSIRIS_FLAWS,predatorDefault,selectedPredator,predatorEffects,predatorRestriction,predatorDisciplines} from './predator.js';
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const KEY='premieres-nuits-v1';let s=blank(),storageOK=true;let traitPage=0;let powerTab=0;let tab='Physique',traitTab='Moyens',traitType='a',search='',pending=null;let toastTimer;let dossierBusy=false;let finalStep=0;
try{const saved=localStorage.getItem(KEY);if(saved)s=importJSON(JSON.parse(saved)).state;}catch{storageOK=false;}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function save(){s.updatedAt=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(s));storageOK=true;}catch{storageOK=false;}const el=$('.save-status');if(el)el.textContent=storageOK?'Enregistré sur cet appareil':'Sauvegarde locale indisponible — exportez le JSON';}
function set(path,v){const parts=path.split('.');let o=s;for(const k of parts.slice(0,-1))o=o[k];o[parts.at(-1)]=v;save();}
function field(label,path,placeholder='',kind='input',extra=''){let val=path.split('.').reduce((a,k)=>a?.[k],s)||'';return `<div class="field"><label for="f-${path}">${label}</label>${kind==='textarea'?`<textarea id="f-${path}" data-field="${path}" placeholder="${esc(placeholder)}" ${extra}>${esc(val)}</textarea><button type="button" class="inline-btn field-expand" data-expand="f-${path}" aria-controls="f-${path}" aria-expanded="false">Agrandir le champ</button>`:`<input id="f-${path}" data-field="${path}" value="${esc(val)}" placeholder="${esc(placeholder)}" ${extra}>`}</div>`;}
function select(label,path,opts){const v=path.split('.').reduce((a,k)=>a?.[k],s);return `<div class="field"><label for="f-${path}">${label}</label><select id="f-${path}" data-field="${path}">${opts.map(([id,name])=>`<option value="${esc(id)}" ${String(id)===String(v)?'selected':''}>${esc(name)}</option>`).join('')}</select></div>`;}
const help=(id,label='i')=>`<button type="button" class="help" data-help="${id}" aria-label="Aide : ${esc(label==='i'?id:label)}">i</button>`;
const pages=['Votre histoire continue.','Votre première nuit commence.','Ce qui vous définit.','Ce que la vie vous a appris.','Ce que vous faites mieux.','Le sang vous a changé.','Comment apaisez-vous la Soif ?','Apprivoisez vos nouveaux dons.','Personne ne survit seul.','Ce qui compte encore.','Une identité pour traverser la nuit.','Votre première nuit vous attend.'];
const intros=[
'Votre personnage humain existe déjà. Retrouvez son dossier, puis donnez-lui les caractéristiques qui permettront de le jouer.',
'Reprenez les informations de votre Étreinte, telles que vous les avez définies avec le conteur.',
'La force, l’agilité, le calme ou la vivacité d’esprit : vos attributs représentent vos capacités générales, avant les apprentissages.',
'Votre profession, vos expériences et vos loisirs ont laissé des traces. Choisissez les compétences qui racontent cette vie.',
'Une spécialité précise un domaine dans lequel vous êtes particulièrement à l’aise. Elle apporte un dé supplémentaire quand elle s’applique.',
'Les disciplines sont les capacités surnaturelles transmises par votre sang. Choisissez les deux que votre personnage possède au départ.',
'Se nourrir devient une nécessité. Votre manière habituelle de trouver du sang peut se découvrir en jeu ou être définie avec le conteur.',
'Chaque point de discipline donne un pouvoir. Prenez le temps de comprendre ce qu’il permet, ce qu’il coûte et ses limites.',
'Votre argent, vos proches et vos difficultés vous suivent dans la nuit. Donnez une portée concrète à ces éléments de votre histoire.',
'Votre nouvelle condition met vos valeurs et vos relations à l’épreuve. Retrouvez les personnes et les projets qui vous font avancer.',
'Le Masque est votre couverture auprès des mortels : le nom, les habitudes et les explications qui rendent votre existence crédible.',
'Relisez votre personnage, corrigez les éléments en attente et conservez une copie de votre travail.'];
const glossary={
attributs:['Attributs et compétences','Un attribut représente une capacité générale ; une compétence représente un apprentissage. Pour négocier un prix, le conteur peut demander Manipulation + Persuasion. Avec 3 et 2, vous lancez cinq dés à dix faces. L’association dépend de votre intention et de la situation.','Livre de base, p. 119–123 et 144.'],
des:['Comprendre un jet','Chaque dé qui affiche 6 ou plus compte comme une réussite. Deux 10 donnent un critique et comptent ensemble pour quatre réussites. Le conteur fixe la difficulté ou oppose le résultat à un autre jet. Les dés de Soif remplacent autant de dés ordinaires, dans la limite du groupement : ils peuvent provoquer un triomphe brutal ou un échec bestial. Vous découvrirez ces conséquences en jeu.','Livre de base, p. 119–123 et 205–207.'],
soif:['Soif et test d’Exaltation','La Soif mesure le besoin de sang, de 0 à 5. Un test d’Exaltation consiste à lancer un dé : 6 ou plus, votre Soif reste stable ; 1 à 5, elle augmente d’un point. Échouer à ce test n’empêche généralement pas le pouvoir de fonctionner. Les pouvoirs gratuits ne demandent pas ce test. La Soif initiale est fixée par la scène avec le conteur.','Livre de base, p. 205–213.'],
sante:['Santé et Volonté','La Santé vaut Vigueur + 3, augmentée par Résilience si vous choisissez ce pouvoir. La Volonté vaut Sang-froid + Résolution. Ce sont des jauges : leur maximum se distingue des dégâts subis. En jeu, dépenser de la Volonté peut notamment permettre de relancer jusqu’à trois dés ordinaires ; les dés de Soif ne se relancent pas ainsi.','Livre de base, p. 144 et 157–158.'],
clan:['Le clan et le sire','Le sire est le vampire qui vous a étreint. Il vous transmet normalement son clan, un héritage de sang associé à trois disciplines et à un fléau. Un clan ne fixe ni votre métier, ni votre personnalité, ni tous vos choix. Le choix se fait avec le conteur, idéalement avant le récit de l’Étreinte.','Livre de base, p. 63–113 et 142 ; Guide du joueur, p. 15–55.'],
generation:['Génération et Puissance du sang','La génération compte les transmissions du sang depuis l’ancêtre mythique. Elle ne mesure pas votre âge humain. Dans ce parcours pour infants de 12e ou 13e génération, la Puissance du sang initiale est 1. Le conteur fixe ces paramètres ; aucun bonus d’expérience d’ancienneté n’est ajouté.','Livre de base, p. 136–137, 149 et 214–216.'],
profils:['Choisir une répartition','Touche-à-tout donne beaucoup de compétences modestes. Équilibré donne plusieurs domaines solides. Spécialiste permet une expertise à 4 points en contrepartie d’une liste plus courte. Choisissez d’après votre personnage. Les compétences non choisies restent à 0 : cela ne rend pas automatiquement toute tentative impossible.','Livre de base, p. 136 et 147.'],
specialites:['Une spécialité, concrètement','« Conduite : poursuites » peut ajouter un dé lors d’une poursuite automobile. Elle ne s’applique pas à toutes les actions de Conduite. Vous recevez une spécialité libre, plus une dans chacune des compétences Artisanat, Érudition, Représentation et Sciences si vous les possédez.','Livre de base, p. 136 et 145–147.'],
disciplines:['Discipline et pouvoir','Une discipline est un domaine surnaturel, comme Auspex. Un pouvoir est une capacité précise de ce domaine, comme Sens accrus. À la création, vous prenez deux disciplines de clan, l’une à 2 et l’autre à 1. Votre deuxième pouvoir peut être de niveau 1 ou 2 ; le premier doit être de niveau 1.','Livre de base, p. 149 et 244.'],
mascarade:['La Mascarade','Les vampires dissimulent leur existence aux mortels. Un pouvoir spectaculaire, une victime ou une trace de sang peuvent attirer des soupçons. Les traditions et les conséquences politiques se découvriront avec le conteur. Les illustrations suggèrent une ambiance ; elles ne définissent pas les capacités de votre personnage.','Livre de base, p. 50–51 et 243.'],
rituel:['Pouvoirs et rituels','La Sorcellerie du sang donne des pouvoirs comme les autres disciplines, et permet aussi l’étude de rituels. Un personnage qui la possède commence avec un rituel de niveau 1. Les rituels demandent préparation, ingrédients et généralement un jet d’Intelligence + Sorcellerie du sang, difficulté niveau + 1. Ils ne sont pas des pouvoirs instantanés gratuits.','Livre de base, p. 272–276.'],
avantages:['Des points et une histoire','Les avantages représentent des moyens utilisables en jeu. Un proche de votre background peut devenir un Allié ou un Contact si vous lui attribuez des points et définissez son aide. Une Attache, elle, représente votre lien à l’humanité. Un handicap ajoute une difficulté réelle ; en prendre davantage ne crée pas automatiquement de points d’avantages.','Livre de base, p. 149–150 et 179–194.'],
convictions:['Convictions, Attaches et Humanité','Une Conviction est un principe personnel important en jeu. Une Attache est un mortel vivant qui l’incarne à vos yeux. Vous choisissez un à trois couples. Les Principes de la chronique sont les règles morales collectives de la partie ; les enfreindre peut entraîner des Flétrissures. Une Conviction peut atténuer certaines Flétrissures lorsque son respect a motivé un acte. Elle ne donne pas une immunité morale générale.','Livre de base, p. 172–173 et 236–241.'],
objectifs:['Ambition et Désir','L’Ambition vous pousse sur la durée : retrouver une personne disparue, protéger une famille ou prendre la direction d’un réseau. Le Désir est un objectif immédiat : obtenir un rendez-vous, retrouver un dossier ou convaincre quelqu’un de vous aider. Il peut changer d’une séance à l’autre.','Livre de base, p. 173–174.'],
refuges:['Avoir un endroit où dormir','Un vampire doit pouvoir se protéger du soleil pendant son sommeil diurne. Ne pas acheter Refuge ne signifie pas automatiquement être sans abri : vous pouvez avoir un logement modeste, ou dépendre d’autres moyens. Le handicap Sans refuge décrit une précarité réelle et impose de chercher un nouvel endroit où dormir.','Livre de base, p. 190–192.'],
references:['Périmètre de cette première version','Le parcours associe le livre de base français et les sept clans supplémentaires du Guide du joueur. Les variantes de fléau sont exclues ; les pouvoirs complémentaires liés aux clans et Néant de niveaux 1 à 3 sont proposés avec leurs prérequis. Le parcours est réglé pour des infants de 12e ou 13e génération, parmi quatorze clans. Caitiffs, Sangs Clairs, Sagas et création collective de coterie restent à traiter avec le conteur hors de ce parcours. Le style de prédation est différé par défaut pour les novices. S’il est défini avec le conteur, ses effets du livre de base sont appliqués. Le lore contemporain n’est pas transposé automatiquement à Chicago 1940, notamment la chute de Vienne.','Références : livre de base ; Guide du joueur p. 15–55, 70–91 ; fiche V5 et « Crée ton vampire » filtré.'],
import:['Importer et sauvegarder','Un JSON de background peut utiliser plusieurs noms de champs courants. Un aperçu indique ceux reconnus ; toutes les données originales restent conservées dans le JSON exporté. Vérifiez les correspondances et complétez ce qui manque. Une sauvegarde créée ici restaure toute la fiche. L’enregistrement local dépend du navigateur et de cet appareil ; téléchargez votre JSON pour conserver et transférer votre travail.','Aucune donnée de personnage n’est envoyée à un serveur par cet assistant.']};
function showModal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();}
function helpModal(id){if(id.startsWith('skill:')){const k=SKILLS.find(x=>x[0]===id.slice(6));showModal(`<h2 id="modal-title">${esc(k[1])}</h2><p>${esc(k[3])}</p><div class="note">Exemples de spécialités : ${esc(k[4])}.</div><p>Votre vécu peut justifier cette compétence. Discutez des associations d’attribut et de compétence avec le conteur selon votre action.</p><div class="ref">Livre de base, p. 159–171.</div>`);return;}if(id.startsWith('attr:')){const a=ATTR.find(x=>x[0]===id.slice(5));showModal(`<h2 id="modal-title">${esc(a[1])}</h2><p>${esc(a[3])}</p><p>1 : faible · 2 : ordinaire · 3 : solide · 4 : remarquable. Choisissez ce qui correspond au personnage.</p><div class="ref">Livre de base, p. 144 et 155–157.</div>`);return;}const [title,txt,ref]=glossary[id]||glossary.references;showModal(`<div class="eyebrow">Comprendre pour choisir</div><h2 id="modal-title">${title}</h2><p>${txt}</p><div class="ref">${ref}</div>`);}
function common(){return `<header class="topbar"><div class="brand"><span class="sigil" aria-hidden="true">V</span><div><strong>VAMPIRE</strong><small>LES PREMIÈRES NUITS</small></div></div><div class="toolbar"><span class="save-status">${storageOK?'Enregistré sur cet appareil':'Export JSON recommandé'}</span><button class="ghost small" data-action="import">Charger JSON</button><button class="ghost small" data-action="export">Sauvegarder JSON</button><button class="ghost small help-top" data-action="guide">Aide</button></div></header>`;}
function render(){const ee=errors(s),done=ee.map(x=>!x.length);
$('#app').innerHTML=common()+`<div class="layout"><aside class="sidebar" aria-label="Étapes de création"><div class="eyebrow">Un personnage prend vie</div><nav class="navlist">${STEPS.map((x,i)=>`<button class="navitem ${i===s.step?'active':''} ${done[i]&&i<STEPS.length-1?'done':''}" data-go="${i}" ${i===s.step?'aria-current="step"':''} aria-label="Étape ${i+1} : ${x[0]}" title="${x[0]}"><span class="navnum">${String(i+1).padStart(2,'0')}</span><span class="navtext">${x[0]}</span></button>`).join('')}</nav><div class="sidebar-note"><span>Chicago · 1940 — V5 · Base et Guide du joueur</span><div class="path-options"><button class="inline-btn" data-help="references">Règles et références</button><button class="inline-btn" data-action="reset">Nouveau personnage</button></div></div></aside><main class="main" id="main"><div class="chapter"><span class="eyebrow">${STEPS[s.step][2]} — ${STEPS[s.step][1]}</span><span class="chapter-count">${String(s.step+1).padStart(2,'0')} / ${STEPS.length}</span></div><div class="progress" aria-label="Progression : étape ${s.step+1} sur ${STEPS.length}"><span style="width:${(s.step+1)/STEPS.length*100}%"></span></div><div class="intro"><h1 tabindex="-1" id="page-title">${pages[s.step]}</h1><p>${intros[s.step]}</p></div>${page(s.step)}${s.step===STEPS.length-1?'':`<footer class="footer"><button class="secondary" data-action="prev" ${s.step===0?'disabled':''}>← Précédent</button><div class="footer-right"><small>${s.step===STEPS.length-1?'Votre dossier vous appartient.':'Vous pouvez revenir sur chaque choix.'}</small><button class="primary" data-action="${s.step===STEPS.length-1?'export':'next'}">${s.step===STEPS.length-1?'Sauvegarder mon JSON':'Continuer →'}</button></div></footer>`}<div class="origin-note">Assistant personnel pour Vampire : La Mascarade V5 · Création guidée · Chicago 1940</div></main></div>`;
if(!storageOK)toast('La sauvegarde locale est indisponible. Exportez régulièrement votre JSON.');
}
function page(i){return [p0,p1,p2,p3,p4,p5,pPred,p6,p7,p8,pMask,p9][i]();}
function p0(){return `<section class="stage"><div class="section-head"><h2>Retrouver votre dossier</h2>${help('import')}</div><div class="upload" id="dropzone"><span class="upload-icon">↥</span><b>Votre histoire commence ici</b><p>Déposez le JSON de votre background humain<br>ou une sauvegarde de cet assistant.</p><button class="secondary small" data-action="import">Choisir un fichier JSON</button><span class="hint">Vous pouvez aussi remplir les champs ci-dessous.</span></div>${s.importInfo?`<div class="note good">Background chargé. Les données originales sont conservées. Vérifiez les champs reconnus et complétez les autres. <button class="inline-btn" data-action="original">Consulter le dossier original</button></div>`:''}<div class="two">${field('Nom du personnage','identity.name','Ex. Eleanor Walsh')}${field('Profession de son vivant','identity.profession','Ex. Infirmière de nuit')}</div>${field('Concept en une phrase','identity.concept','Ex. Une infirmière obstinée qui protège les oubliés du quartier')}<div class="two">${field('Date de naissance · facultative','identity.birth','Ex. 14 mars 1908')}${field('Âge lors de l’Étreinte','identity.age','Ex. 32 ans')}</div><details><summary>Relire l’apparence et les possessions</summary><div style="margin-top:18px">${field('Apparence et signes distinctifs','identity.appearance','Silhouette, visage, vêtements…','textarea')}${field('Possessions habituelles','identity.possessions','Objets utiles, objet précieux…','textarea')}${field('Notes à discuter avec le conteur','identity.notes','','textarea')}</div></details></section>`;}
function p1(){const clan=CLANS[s.embrace.clan],guide=CLAN_GUIDE[s.embrace.clan];return `<section class="stage embrace-stage"><div class="section-head"><h2>Votre Étreinte</h2></div><div class="two">${field('Votre sire','embrace.sire','Son nom, ou « identité inconnue »')}${field('Quand avez-vous été étreint ?','embrace.date','Ex. Octobre 1940')}</div><div class="field"><label for="clan-select">Votre clan</label><select id="clan-select" data-clan-select><option value="" disabled ${!clan?'selected':''}>Choisir avec le conteur</option>${[['Livre de base',false],['Guide du joueur',true]].map(([label,extra])=>`<optgroup label="${label}">${Object.entries(CLANS).filter(([,c])=>Boolean(c.source)===extra).map(([id,c])=>`<option value="${id}" ${s.embrace.clan===id?'selected':''}>${c.name}</option>`).join('')}</optgroup>`).join('')}</select></div><details class="embrace-detail"><summary>Besoin d’aide pour choisir le clan ?</summary><div class="detail-body"><p class="muted">Le clan est transmis par votre sire. Arrêtez ce choix avec le conteur avant le récit de l’Étreinte.</p><p class="muted">Le <a href="https://zebigboss4396d.github.io/personnalit--vtm/" target="_blank" rel="noopener noreferrer">test de personnalité Vampire : La Mascarade</a> peut servir de point de départ. Validez ensuite votre choix avec le conteur, parmi les clans proposés ici.</p></div></details>${clan?`<section class="clan-profile" aria-label="Découvrir le clan ${clan.name}"><header class="clan-profile-head"><img class="clan-symbol" src="./assets/clans/${clan.symbol||s.embrace.clan+'.svg'}" alt="Symbole du clan ${clan.name}" width="82" height="100"><div><h3>${clan.name}</h3><p>${clan.tag}</p></div></header><p class="clan-summary">${guide.description}</p>${clan.history?`<div class="note warn"><b>Chicago 1940 · à valider avec le conteur</b><br>${esc(clan.history)}</div>`:''}<h3 class="clan-weakness-title">Votre fléau de clan</h3><p class="hint">Chaque clan transmet une faiblesse surnaturelle, appelée « fléau ». Voici ce qu’elle signifie pour votre personnage.</p><p class="clan-weakness">${guide.weakness}</p><div class="bane-facts"><div><h4>Quand intervient-il ?</h4><p>${guide.when}</p></div><div><h4>Conséquence en jeu</h4><p>${guide.rule}</p></div><div class="bane-example"><h4>Exemple concret · à adapter à votre personnage</h4><p>${guide.example}</p></div></div><div class="ref">${clan.source||'Livre de base'}, p. ${clan.page}.</div>${guide.compulsion?`<details class="embrace-detail"><summary>La Compulsion de votre clan</summary><div class="detail-body"><p class="hint">Une Compulsion est une impulsion de la Bête qui peut survenir en jeu. Elle ne remplace pas votre personnalité.</p><p class="muted">${esc(guide.compulsion)}</p></div></details>`:''}<div class="clan-specific">${field('Comment cette faiblesse se manifeste-t-elle chez vous ?','embrace.clanDetail','Décrivez ici les manifestations concrètes retenues avec le conteur.','textarea')}<p class="hint">À décrire ensemble, joueur et conteur. ${guide.prompt}</p></div><details class="embrace-detail"><summary>Les disciplines de votre clan</summary><div class="detail-body">${clan.disc.map(d=>`<p class="muted"><b>${DISC[d][0]}</b> · ${DISC[d][1]}</p>`).join('')}<p class="hint">Vous choisirez vos disciplines et vos pouvoirs dans les étapes suivantes.</p></div></details></section>`:''}<details class="embrace-detail"><summary>Paramètres fixés avec le conteur</summary><div class="detail-body"><div class="two">${select('Génération','embrace.generation',[[13,'13e génération'],[12,'12e génération']])}${select('Humanité initiale','embrace.humanity',[[7,'7 — valeur habituelle'],[8,'8 — avec l’accord du conteur']])}</div><p class="muted">Infant récemment étreint · Puissance du sang : 1 · Expérience : 0.</p><p class="hint">À l’étape « Se nourrir », vous pourrez différer ce choix ou le définir avec le conteur. La Soif sera fixée au début de la scène.</p></div></details><label class="checklabel embrace-confirm"><input type="checkbox" data-field="embrace.confirmed" ${s.embrace.confirmed?'checked':''}><span>Ces informations sont confirmées avec le conteur.</span></label></section>`;}
function p2(){const expected={4:1,3:3,2:4,1:1},d=derived(s);return `<section class="stage"><div class="section-head"><h2>Un point fort. Une fragilité.</h2>${help('attributs')}</div><p class="muted">Choisissez un score pour chaque attribut. Commencez par votre meilleur et votre plus faible, puis répartissez les autres.</p><div class="points">${[4,3,2,1].map(n=>{const count=Object.values(s.attributes).filter(v=>v===n).length;return `<span class="${count===expected[n]?'ok':'wrong'}"><b>${n}</b> points : ${count}/${expected[n]}</span>`;}).join('')}</div><div class="three">${['Physique','Social','Mental'].map(g=>`<section class="attr-group"><h3>${g}</h3>${ATTR.filter(a=>a[2]===g).map(([id,name,,desc])=>`<div class="attr-row"><div class="attr-name">${name}${help('attr:'+id,name)}</div><div class="dots" role="group" aria-label="Score de ${name}">${[1,2,3,4].map(n=>`<button class="dot ${s.attributes[id]>=n?'filled':''}" data-attr="${id}" data-value="${n}" aria-label="${name} : ${n} points" aria-pressed="${s.attributes[id]===n}">${n}</button>`).join('')}</div><div class="hint">${desc}</div></div>`).join('')}</section>`).join('')}</div><div class="derived"><div><b>${d.health}</b><small>Santé · Vigueur + 3${Object.values(s.powers).flat().includes('resilience')?' + Résilience':''}</small></div><div><b>${d.willpower}</b><small>Volonté · Sang-froid + Résolution</small></div>${help('sante')}</div><div class="ref">Livre de base, p. 144–158.</div></section>`;}
function p3(){const prof=PROFILES[s.profile];return `<section class="stage"><div class="section-head"><h2>Votre manière de savoir faire</h2>${help('profils')}</div><div class="three">${Object.entries(PROFILES).map(([id,p])=>`<button class="choice ${s.profile===id?'selected':''}" data-profile="${id}" aria-pressed="${s.profile===id}"><strong>${p.name}</strong><small>${p.desc}</small><div class="profile-stats">${[4,3,2,1].filter(n=>p.slots.includes(n)).map(n=>`${p.slots.filter(x=>x===n).length} à ${n}`).join(' · ')}</div></button>`).join('')}</div>${s.identity.profession?`<div class="note">Votre vécu : <b>${esc(s.identity.profession)}</b>${s.identity.concept?' · '+esc(s.identity.concept):''}. Appuyez-vous sur cette histoire pour choisir.</div>`:''}<div class="points">${[4,3,2,1].filter(n=>prof.slots.includes(n)||Object.values(s.skills).includes(n)).map(n=>{const count=Object.values(s.skills).filter(v=>v===n).length,target=prof.slots.filter(v=>v===n).length;return `<span class="${count===target?'ok':'wrong'}"><b>${n}</b> points : ${count}/${target}</span>`;}).join('')}</div><div class="tabs" role="group" aria-label="Famille de compétences">${['Physique','Social','Mental'].map(g=>`<button class="tab ${g===tab?'active':''}" data-tab="${g}" aria-pressed="${g===tab}">${g} <span class="hint">${SKILLS.filter(k=>k[2]===g&&s.skills[k[0]]>0).length}/9</span></button>`).join('')}</div>${SKILLS.filter(k=>k[2]===tab).map(([id,name,,desc])=>`<div class="skillrow"><div><strong>${name}</strong><span class="hint">${desc}</span></div><select data-skill="${id}" aria-label="Score de ${name}">${[0,1,2,3,4].map(n=>`<option value="${n}" ${s.skills[id]===n?'selected':''}>${n}</option>`).join('')}</select>${help('skill:'+id,name)}</div>`).join('')}<div class="note">${predatorEffects(s).specialty?.point?`La prédation ajoute 1 point en ${SKILLS.find(x=>x[0]===predatorEffects(s).specialty.skill)[1]}, actuellement à 0 dans votre répartition de base. Ce bonus est conservé séparément. `:""}Les compétences non choisies restent à 0. Le site suit votre répartition ; il ne choisit pas votre métier ou vos compétences à votre place.</div><div class="ref">Livre de base, p. 136, 147 et 159–171.</div></section>`;}
function p4(){const auto=SPECIAL.filter(id=>s.skills[id]>0);return `<section class="stage"><div class="section-head"><h2>Des talents plus précis</h2>${help('specialites')}</div><p class="muted">Une spécialité s’applique à une partie de la compétence. « Jazz » est plus précis que « Musique » ; « Poursuites » précise une manière de conduire.</p>${auto.length?`<h3>Vos spécialités gratuites de compétence</h3>${auto.map(id=>{const k=SKILLS.find(x=>x[0]===id);return field(k[1]+' · '+s.skills[id]+' point(s)','specialties.'+id,k[4]);}).join('')}`:'<div class="note">Aucune spécialité automatique pour le moment. Artisanat, Érudition, Représentation et Sciences en donnent une si vous y placez des points.</div>'}<h3>Votre spécialité libre</h3><div class="two">${select('Compétence concernée','freeSpecialty.skill',[['','Choisir une compétence'],...SKILLS.filter(x=>s.skills[x[0]]>0).map(x=>[x[0],x[1]])])}${field('Spécialité','freeSpecialty.text',s.freeSpecialty.skill?SKILLS.find(x=>x[0]===s.freeSpecialty.skill)?.[4]:'Ex. Poursuites, interrogatoire…')}</div><div class="note">Exemple : Dextérité 3 + Conduite 2 = cinq dés. Si votre spécialité Poursuites s’applique, vous en lancez six.</div><div class="ref">Livre de base, p. 136 et 145–147.</div></section>`;}
function p5(){const c=CLANS[s.embrace.clan];if(!c)return `<section class="stage"><h2>Votre héritage reste à préciser</h2><p class="muted">Choisissez d’abord votre clan avec le conteur.</p><button class="secondary" data-go="1">Revenir au clan →</button></section>`;return `<section class="stage"><div class="section-head"><h2>Les dons ${c.name==='Ventrue'?'des Ventrues':'de votre clan'}</h2>${help('disciplines')}</div><p class="muted">Choisissez une discipline principale à <b>2 points</b>, puis une autre à <b>1 point</b>. Il s’agit de votre répartition de base. Un style de prédation défini à l’étape suivante peut ajouter un point.</p>${c.disc.map(id=>`<div class="trait-card"><h3>${DISC[id][0]}</h3><p>${DISC[id][1]}</p><div class="trait-controls"><button class="${s.disciplines.major===id?'primary':'secondary'} small" data-disc="${id}" data-slot="major" aria-pressed="${s.disciplines.major===id}">Principale · 2 points ${s.disciplines.major===id?'✓':''}</button><button class="${s.disciplines.minor===id?'primary':'secondary'} small" data-disc="${id}" data-slot="minor" aria-pressed="${s.disciplines.minor===id}">Seconde · 1 point ${s.disciplines.minor===id?'✓':''}</button></div><div class="ref">Livre de base, p. ${DISC[id][2]}.</div></div>`).join('')}<div class="note">Après votre choix de prédation, vous choisirez vos pouvoirs précis. Les points ne donnent pas accès à tous les pouvoirs de la discipline.</div></section>`;}
function predatorSpecialty(s,id){const x=predatorEffects(s).specialty;return x&&x.skill===id&&!x.point?x.text:'';}
function predatorTraitList(){return `<ul class="predator-effects">${predatorEffects(s).traits.map(t=>`<li><b>${TRAITS.find(x=>x.id===t.id)?.name} ${t.level}</b>${t.detail?' · '+esc(t.detail):''}<div class="hint">${esc(traitLevelText(TRAITS.find(x=>x.id===t.id),t.level,t))}</div></li>`).join('')}</ul>`;}
function predatorSummary(){const p=selectedPredator(s),fx=predatorEffects(s),d=derived(s);return p?`<p><b>${p.name}</b>${predatorRestriction(s)?' — choix incompatible à corriger':''}</p><p>${esc(s.predator.description)}</p>${fx.specialty?`<p>${fx.specialty.point?'1 point de compétence':'Spécialité'} : ${SKILLS.find(x=>x[0]===fx.specialty.skill)[1]}${fx.specialty.point?'':' ('+esc(fx.specialty.text)+')'}</p>`:''}${fx.discipline?`<p>Discipline offerte : ${DISC[fx.discipline][0]} +1</p>`:''}${fx.humanity||fx.potency?`<p>Humanité : ${d.humanity}${fx.potency?' · Puissance du sang : '+d.bloodPotency:''}</p>`:''}`:'<p>Style de prédation différé : votre manière de chasser se découvrira en jeu. Aucun effet appliqué.</p>';}
function pPred(){const p=selectedPredator(s),c=s.predator,fx=predatorEffects(s),restriction=predatorRestriction(s),spec=p?.specialties.find(([id])=>id===c.specialty),ee=predatorErrors(s);return `<section class="stage predator-stage"><h2>Une habitude… ou une découverte</h2><p class="muted">Un style de prédation décrit votre manière habituelle d’obtenir du sang. Il ne vous oblige pas à chasser toujours de la même façon.</p>${select('Où en êtes-vous ?','predator.mode',[['deferred','Je découvre encore comment me nourrir'],['defined','Je définis mon style avec le conteur']])}${c.mode==='deferred'?`<div class="note">Pour un vampire récemment étreint, ce choix peut attendre. Vous découvrirez vos habitudes pendant les premières parties. Aucun bonus ni handicap de prédation n’est appliqué.</div><div class="ref">Livre de base, p. 149.</div>`:`${select('Votre style de prédation','predator.style',[['','Choisir un style du livre de base'],...Object.entries(PREDATORS).map(([id,x])=>[id,x.name])])}${p?`<div class="predator-profile"><h3>${p.name}</h3><p>${p.description}</p><p class="hint"><b>À Chicago en 1940 :</b> ${p.example}</p></div>${restriction?`<div class="errors">${restriction} Choisissez un autre style pour appliquer ses effets.</div>`:`<h3>Les deux choix à faire</h3><div class="two">${select('Compétence de prédation','predator.specialty',[['','Choisir une compétence'],...p.specialties.map(([id,name])=>[id,SKILLS.find(x=>x[0]===id)[1]+' · '+name])])}${select('Un point de discipline offert','predator.discipline',[['','Choisir une discipline'],...predatorDisciplines(s).map(d=>[d,DISC[d][0]+' +1 → '+(baseScore(s,d)+1)+' point(s) au total'])])}</div>${spec?`<div class="note">${fx.specialty.point?`Vous n’avez pas de point de base en ${SKILLS.find(x=>x[0]===spec[0])[1]}. Vous gagnez donc <b>1 point de compétence</b>, à la place de la spécialité.`:`Vous gagnez la spécialité <b>${SKILLS.find(x=>x[0]===spec[0])[1]} (${esc(spec[2]?c.specialtyDetail||'à préciser':spec[1])})</b>, soit un dé supplémentaire quand elle s’applique.`}</div>${spec[2]&&!fx.specialty.point?field('Précisez le domaine de votre spécialité','predator.specialtyDetail','Ex. Chats, spiritisme, jazz, milieu du théâtre…'):''}`:''}${p.flaws?select('La complication qui vous accompagne','predator.flaw',[['','Choisir le handicap'],...p.flaws]):''}${c.style==='osiris'?osirisChoices():''}<details class="predator-impact" open><summary>Ce que ce style ajoute à votre fiche</summary>${predatorTraitList()}${p.humanity?`<p>Humanité : ${s.embrace.humanity} ${p.humanity>0?'+':'−'} 1 = <b>${derived(s).humanity}</b></p>`:''}${p.potency?`<p>Puissance du sang : 1 + 1 = <b>2</b>. Régénération : 2 dégâts superficiels par Exaltation ; +1 dé aux pouvoirs de discipline ; deux fois plus de sang animal ou conservé nécessaire.</p>`:''}<p class="hint">Le point de discipline ouvre un pouvoir supplémentaire à choisir à l’étape suivante. Les avantages et handicaps reçus ici s’ajoutent aux 7 points d’avantages et aux 2 points minimum de handicaps de votre création.</p></details>${field('Dans les faits, comment vous nourrissez-vous ?','predator.description','Où trouvez-vous du sang ? Sur qui ? Comment approchez-vous vos victimes ? Précisez aussi vos contacts, ennemis, fidèles, secrets ou tabous avec le conteur.','textarea')}${ee.length?`<p id="predator-status" class="hint">À compléter : ${ee.map(esc).join(' ')}</p>`:'<p id="predator-status" class="hint">Les effets sont intégrés à votre fiche. Confirmez ce choix avec le conteur.</p>'}` }<div class="ref">Livre de base, p. 149 et ${p.page}.</div>`:''}`}</section>`;}
function osirisChoices(){const c=s.predator;const opts=[['','Aucun handicap sur cette ligne'],...OSIRIS_FLAWS.flatMap(id=>{const t=TRAITS.find(x=>x.id===id);return t.levels.map(n=>[id+':'+n,t.name+' · '+n+' point(s)']);})];return `<div class="osiris-choices"><h3>Vos fidèles et vos difficultés</h3>${select('Répartition des 3 points offerts','predator.fame',[0,1,2,3].map(n=>[n,'Renommée '+n+' / Troupeau '+(3-n)]))}<p class="hint">Choisissez exactement 2 points parmi Ennemi et Mythes et légendes. Par exemple : un Ennemi à 2, ou deux handicaps à 1.</p>${[0,1].map(i=>{const x=c.osirisFlaws[i];return `<div class="field"><label for="osiris-${i}">Handicap Osiris ${i+1}</label><select id="osiris-${i}" data-osiris-flaw="${i}">${opts.map(([id,name])=>`<option value="${id}" ${id===(x?.id?x.id+':'+x.level:'')?'selected':''}>${name}</option>`).join('')}</select></div>${x?.id?field('Manifestation du handicap '+(i+1),'predator.osirisFlaws.'+i+'.detail','Quelle menace, faiblesse ou réaction précise ?'):''}`;}).join('')}</div>`;}
function p6(){if(!s.disciplines.major||!s.disciplines.minor)return `<section class="stage"><h2>Choisissez vos disciplines</h2><p class="muted">Deux disciplines sont nécessaires pour sélectionner vos pouvoirs.</p><button class="secondary" data-go="5">Choisir mes disciplines →</button></section>`;
const slots=disciplineIds(s).flatMap(d=>Array.from({length:score(s,d)},(_,slot)=>({d,slot})));if(score(s,'sorcellerie'))slots.push({ritual:true});if(score(s,'neant'))slots.push({ceremony:true});powerTab=Math.min(powerTab,slots.length-1);const active=slots[powerTab];let content='';
if(active.ceremony){const available=CEREMONIES.filter(c=>(s.powers.neant||[]).includes(c.power));content=`<div class="disc-slot"><h3>Cérémonie initiale · facultative</h3></div><p class="muted">Vous pouvez choisir une cérémonie de niveau 1 si vous possédez son pouvoir prérequis. Elle est distincte des pouvoirs de discipline.</p>${select('Votre cérémonie','ceremony',[['','Aucune pour le moment'],...available.map(c=>[c.id,c.name])])}${available.map(c=>`<div class="note"><b>${c.name}</b><br>${esc(c.description)}<div class="ref">Prérequis : ${esc(POWERS.find(p=>p.id===c.power)?.name)} · Guide du joueur p. ${c.page}.</div></div>`).join('')}${!available.length?'<p class="hint">Choisissez Cendres tu es ou Entraves des morts pour accéder à la cérémonie associée.</p>':''}`;}else if(active.ritual)content=`<div class="disc-slot"><h3>Votre rituel initial</h3><span class="hint">Choisissez un rituel de niveau 1.</span></div>${RITUALS.map(([id,name,desc,pg])=>`<label class="power ${s.ritual===id?'selected':''}"><input type="radio" name="ritual" data-ritual="${id}" ${s.ritual===id?'checked':''}><div><h3>${name}</h3><p>${desc}</p><span class="hint">Niveau 1 · Préparation et ingrédients requis · Livre p. ${pg}</span></div></label>`).join('')}`;
else{const {d,slot}=active,selected=s.powers[d]?.[slot],previous=slot===0||Array.from({length:slot},(_,i)=>s.powers[d]?.[i]).every(Boolean);content=`<div class="disc-slot"><h3>${DISC[d][0]} · pouvoir ${slot+1}/${score(s,d)}</h3><div class="hint">${slot===0?'Choisissez un pouvoir de niveau 1.':'Choisissez un pouvoir différent de niveau 1 à '+(slot+1)+'.'}</div></div>${!previous?'<div class="note">Choisissez d’abord les pouvoirs précédents de cette discipline.</div>':''}${POWERS.filter(p=>p.disc===d&&p.level<=slot+1).map(p=>{const duplicate=(s.powers[d]||[]).some((id,i)=>i!==slot&&id===p.id),disabled=!previous||!powerAllowed(s,p)||duplicate;return `<div class="power ${selected===p.id?'selected':''} ${disabled?'disabled':''}"><input type="radio" name="power-${d}-${slot}" id="power-${d}-${slot}-${p.id}" data-power="${p.id}" data-disc="${d}" data-slot="${slot}" ${selected===p.id?'checked':''} ${disabled?'disabled':''}><div><label class="power-label" for="power-${d}-${slot}-${p.id}"><h3>${p.name} <span class="level">NIV. ${p.level}</span></h3></label><p>${p.effect}</p>${!powerAllowed(s,p)?`<div class="hint">Prérequis : ${[...Object.entries(p.requires).map(([id,n])=>DISC[id][0]+' '+n),...(p.requiresPower?[POWERS.find(x=>x.id===p.requiresPower)?.name]:[])].join(', ')}</div>`:''}${duplicate?'<div class="hint">Déjà choisi pour un autre point.</div>':''}<details><summary>Coût, jet et limites</summary><p><b>Coût :</b> ${p.cost}<br><b>Jet :</b> ${p.roll}<br><b>Limites :</b> ${p.limit}</p><div class="ref">${p.source||'Livre de base'}, p. ${p.page}.</div></details></div></div>`;}).join('')}`;}
return `<section class="stage"><div class="section-head"><h2>Un pouvoir à la fois</h2>${help('disciplines')}</div><div class="tabs" aria-label="Sous-étapes des pouvoirs">${slots.map((x,i)=>`<button class="tab ${i===powerTab?'active':''}" data-power-tab="${i}">${x.ceremony?'Cérémonie':x.ritual?'Rituel':DISC[x.d][0]+' · '+(x.slot+1)} ${x.ceremony?s.ceremony?'✓':'':x.ritual?s.ritual?'✓':'':s.powers[x.d]?.[x.slot]?'✓':''}</button>`).join('')}</div>${content}${score(s,'neant')?'<div class="note warn"><b>Néant : attention aux Flétrissures.</b> Un 1 ou un 10 sur un test d’Exaltation de Néant inflige une Flétrissure. La discipline est limitée par la lumière ; éclairage modéré : −1 dé, zones très lumineuses : pouvoirs inopérants. Guide p. 83–84.</div>':''}${powerTab<slots.length-1?`<button class="secondary small" data-power-tab="${powerTab+1}">Choix suivant →</button>`:''}<div class="note">Les résumés aident au choix. Les conditions générales de chaque discipline et les précisions du livre continuent de s’appliquer.</div></section>`;}
function traitLevelGuide(t,level,choice={}){const g=TRAIT_GUIDE[t.id];const row=(n,text)=>`<tr><th scope="row">${n} point${Number(n)>1?'s':''}</th><td>${esc(text)}</td></tr>`;const table=levels=>`<table class="level-table"><tbody>${Object.entries(levels).map(([n,text])=>row(n,text)).join('')}</tbody></table>`;return `<div class="trait-level-current" data-trait-effect="${t.id}" aria-live="polite"><b>${t.allies?'Coût total':t.levels.length===1?'Coût fixe':'Niveau choisi'} : ${level} point${level>1?'s':''}</b><p>${esc(traitLevelText(t,level,choice))}</p></div>${t.allies?`<details class="trait-levels"><summary>Comprendre l’Efficacité et la Fiabilité</summary><h4>Efficacité · capacité à vous aider</h4>${table(g.efficacy)}<h4>Fiabilité · disponibilité</h4>${table(g.reliability)}<p class="hint">${esc(g.note)}</p></details>`:`${t.levels.length>1?`<details class="trait-levels"><summary>Comparer les niveaux</summary>${table(g.levels)}${g.note?`<p class="hint">${esc(g.note)}</p>`:''}</details>`:g.note?`<p class="hint">${esc(g.note)}</p>`:''}`}`;}
function refreshTraitLevel(id){const t=TRAITS.find(t=>t.id===id);if(!t)return;const choice=t.allies?{efficacy:Number($('#eff-'+id).value),reliability:Number($('#fiab-'+id).value)}:{};const level=t.allies?choice.efficacy+choice.reliability:Number($('#level-'+id).value),el=document.querySelector('[data-trait-effect="'+id+'"]');if(el)el.innerHTML=`<b>${t.allies?'Coût total':'Niveau choisi'} : ${level} point${level>1?'s':''}</b><p>${esc(traitLevelText(t,level,choice))}</p>`;}
function p7(){const all=TRAITS.filter(t=>t.type===traitType&&t.group===traitTab&&(t.name+' '+t.desc).toLowerCase().includes(search.toLowerCase()));const pages=Math.max(1,Math.ceil(all.length/5));traitPage=Math.min(traitPage,pages-1);const list=all.slice(traitPage*5,traitPage*5+5);return `<section class="stage"><div class="section-head"><h2>Des appuis. Des complications.</h2>${help('avantages')}</div><p class="hint">Le nombre de points est le coût total du trait : un avantage à 3 points coûte 3, pas 1 + 2 + 3. Les handicaps doivent totaliser au moins 2 points ; ils n’augmentent pas vos 7 points d’avantages.</p><div class="points"><span class="${budget(s,'a')===7?'ok':'wrong'}"><b>${budget(s,'a')}</b> / 7 points d’avantages</span><span class="${budget(s,'h')>=2?'ok':'wrong'}"><b>${budget(s,'h')}</b> / 2 minimum de handicaps</span></div><div class="tabs"><button class="tab ${traitType==='a'?'active':''}" data-trait-type="a">Avantages</button><button class="tab ${traitType==='h'?'active':''}" data-trait-type="h">Handicaps</button></div><div class="tabs" aria-label="Famille d’avantages">${['Moyens','Relations','Refuge','Personnel','Se nourrir'].map(g=>`<button class="tab ${traitTab===g?'active':''}" data-trait-tab="${g}">${g}</button>`).join('')}</div>${pages>1?`<div class="section-head"><span class="hint">Choix ${traitPage*5+1} à ${Math.min(all.length,traitPage*5+5)} sur ${all.length}</span><div><button class="ghost small" data-trait-page="${traitPage-1}" ${traitPage===0?'disabled':''} aria-label="Choix précédents">←</button> <button class="ghost small" data-trait-page="${traitPage+1}" ${traitPage===pages-1?'disabled':''} aria-label="Choix suivants">→</button></div></div>`:''}<div class="trait-layout"><div>${list.length?list.map(t=>{const issue=traitIssue(s,t),over=t.type==='a'&&t.levels[0]>7-budget(s,'a'),selectedLevel=t.allies?1:(t.levels.find(n=>t.type!=='a'||n<=7-budget(s,'a'))??t.levels[0]);return `<div class="trait-card"><h3>${t.name}</h3><p>${t.desc}</p>${t.allies?`<div class="two"><div class="field"><label for="eff-${t.id}">Efficacité</label><select id="eff-${t.id}" data-trait-level="${t.id}">${[1,2,3,4].map(n=>`<option value="${n}">${n}</option>`).join('')}</select></div><div class="field"><label for="fiab-${t.id}">Fiabilité</label><select id="fiab-${t.id}" data-trait-level="${t.id}">${[0,1,2,3].map(n=>`<option value="${n}">${n}</option>`).join('')}</select></div></div>`:''}<div class="trait-controls">${!t.allies?`<select id="level-${t.id}" data-trait-level="${t.id}" aria-label="Coût en points : ${t.name}">${t.levels.map(n=>`<option value="${n}" ${n===selectedLevel?'selected':''} ${t.type==='a'&&n>7-budget(s,'a')?'disabled':''}>${n} pt${n>1?'s':''}</option>`).join('')}</select>`:'<span class="hint">Coût = Efficacité + Fiabilité</span>'}<button class="secondary small" data-add="${t.id}" ${issue||over?'disabled':''}>Ajouter +</button></div>${traitLevelGuide(t,selectedLevel,{efficacy:1,reliability:0})}${issue?`<div class="hint">${issue}</div>`:''}<div class="ref">Livre de base, p. ${t.page}.</div></div>`;}).join(''):'<p class="empty">Aucun choix dans cette famille.</p>'}</div><aside class="basket" aria-label="Choix retenus"><h3>Votre sélection de base</h3>${s.traits.length?s.traits.map((x,i)=>{const t=TRAITS.find(t=>t.id===x.id);return `<div class="basket-item"><b>${esc(t.name)}</b> · ${x.level} pt${x.level>1?'s':''}<div class="hint">${t.type==='a'?'Avantage':'Handicap'}${t.allies?' · E'+x.efficacy+' / F'+x.reliability:''}</div><p class="hint selected-trait-effect">${esc(traitLevelText(t,x.level,x))}</p>${t.detail?`<div class="field"><label for="trait-detail-${i}">Qui, quoi, et dans quelles conditions ?</label><textarea id="trait-detail-${i}" data-trait-detail="${i}" placeholder="Précisez ce choix…">${esc(x.detail)}</textarea></div>`:''}<button class="remove" data-remove="${i}">Retirer</button></div>`;}).join(''):'<p class="empty">Vos choix apparaîtront ici.</p>'}${predatorEffects(s).traits.length?`<div class="predator-grants"><h3>Reçus par la prédation</h3>${predatorTraitList()}<p class="hint">Hors du budget de 7 points et des 2 handicaps de base. Modifiables à l’étape « Se nourrir ».</p></div>`:''}${s.embrace.clan==='nosferatu'?'<div class="note">Repoussant est imposé par votre fléau et ne compte pas dans les handicaps achetés.</div>':''}</aside></div></section>`;}
function p8(){return `<section class="stage"><div class="section-head"><h2>Ce qui reste humain</h2>${help('convictions')}</div><p class="muted">Reprenez vos éléments de background. Chaque Attache est un mortel vivant ; indiquez comment cette personne incarne votre Conviction.</p>${s.connections.map((x,i)=>`<section class="pair"><div class="pair-header"><h3>Lien ${i+1}</h3>${s.connections.length>1?`<button class="remove" data-remove-pair="${i}">Retirer ce lien</button>`:''}</div>${field('Conviction','connections.'+i+'.conviction','Ex. Ne jamais abandonner quelqu’un qui dépend de moi.','textarea')}${field('Nom de l’Attache mortelle','connections.'+i+'.name','Une personne vivante')}${field('Le lien entre cette personne et votre Conviction','connections.'+i+'.relation','Qui est-elle ? Qu’incarne-t-elle ?','textarea')}</section>`).join('')}${s.connections.length<3?'<button class="secondary small" data-action="pair">Ajouter une Conviction et une Attache +</button>':''}<div class="note">Une Attache peut aussi avoir un rôle dans vos avantages, mais être une Attache ne lui donne pas automatiquement des points d’Allié ou de Contact.</div></section><section class="stage"><div class="section-head"><h2>Des raisons d’avancer</h2>${help('objectifs')}</div>${field('Ambition · un objectif durable','ambition','Ex. Mettre ma sœur définitivement à l’abri.','textarea')}${field('Désir · ce que vous voulez obtenir maintenant','desire','Ex. Retrouver le médecin qui m’a vu la nuit de ma disparition.','textarea')}${field('Principes de la chronique · à définir avec le groupe','principles','Les principes moraux retenus ensemble.','textarea')}${field('Où dormez-vous désormais ?','night.refuge','Un lieu confirmé ou à discuter avec le conteur.','textarea')}${field('Possessions encore accessibles après l’Étreinte','night.possessions','Ce que vous pouvez réellement utiliser maintenant.','textarea')}<div class="ref">Livre de base, p. 146–150 et 172–174.</div></section>`;}
const maskLabels={name:'Nom utilisé auprès des mortels',activity:'Activité et histoire de couverture',daytime:'Expliquer vos absences et vos habitudes',documents:'Documents et traces administratives',supports:'Les personnes qui soutiennent votre couverture',risks:'Les failles et les questions à discuter'};
function maskSummary(){return `<div class="review-block"><h3>Le Masque</h3><p class="long-text">${esc(s.night.mask||'Couverture encore à définir avec le conteur.')}</p>${Object.entries(maskLabels).filter(([key])=>s.mask[key]).map(([key,label])=>`<p class="long-text"><b>${label}</b><br>${esc(s.mask[key])}</p>`).join('')}</div>`;}
function pMask(){const level=s.traits.find(t=>t.id==='masque')?.level||0;return `<section class="stage"><h2>À quoi sert le Masque ?</h2><p class="muted">Vous êtes un vampire, mais vos voisins, votre employeur et les administrations doivent pouvoir croire à une vie humaine. Le Masque est cette identité de couverture. La Mascarade, elle, est le secret qui protège l’existence des vampires.</p><p class="muted">Un infant peut encore utiliser sa véritable identité. Vous n’avez pas à inventer immédiatement un autre nom. Commencez par expliquer ce qui a changé depuis l’Étreinte.</p>${field('Votre situation actuelle auprès des mortels','night.mask','Identité conservée, disparition, décès annoncé, nouvelle identité ou décision encore en attente…','textarea')}<div class="note">Exemple : Vicky garde son nom et prétend travailler la nuit. Sa sœur croit qu’elle dort le jour, mais son ancien employeur attend toujours des explications.</div></section><section class="stage"><h2>Construire votre couverture</h2><p class="muted">Ces précisions sont facultatives. Développez les réponses utiles avec le conteur ; les champs peuvent être agrandis pour lire vos textes.</p>${field(maskLabels.name,'mask.name','Votre vrai nom, un pseudonyme ou une identité empruntée.')}${field(maskLabels.activity,'mask.activity','Quel métier ou rôle affichez-vous ? Que dites-vous de votre passé ?','textarea')}${field(maskLabels.daytime,'mask.daytime','Pourquoi êtes-vous absent le jour ? Comment justifiez-vous vos nouveaux horaires et vos repas évités ?','textarea')}<details class="embrace-detail"><summary>Documents, soutiens et failles</summary><div class="detail-body">${field(maskLabels.documents,'mask.documents','À Chicago en 1940 : courrier, bail, dossier professionnel, actes d’état civil… Qui pourrait les vérifier ?','textarea')}${field(maskLabels.supports,'mask.supports','Qui confirme votre histoire ? Que sait cette personne et pourquoi vous aide-t-elle ?','textarea')}${field(maskLabels.risks,'mask.risks','Un proche inquiet, une signature incohérente, une obligation en journée… Que reste-t-il à régler ?','textarea')}</div></details></section><section class="stage"><h2>Votre protection dans les règles</h2><p class="muted">Décrire une couverture ne donne aucun avantage gratuit. L’historique Masque mesure la solidité de votre fausse identité lors des vérifications.</p><div class="note"><b>Masque actuellement acheté : ${level} point${level>1?'s':''}.</b> ${level===0?'À 0 point, vous pouvez garder votre identité humaine ou disposer d’une couverture très superficielle. Une fausse identité de ce niveau ne résiste pas à une enquête sur vos antécédents.':level===1?'À 1 point, votre fausse identité est étayée par des documents et résiste aux vérifications de la police locale.':'À 2 points, votre fausse identité peut résister aux vérifications des meilleurs services de police.'}</div><p class="muted">Les points se dépensent dans « Avantages & handicaps », parmi les 7 points de création. Fantôme et Costumier nécessitent Masque 2. Les documents et les contrôles sont à adapter aux archives et aux institutions de 1940 avec le conteur.</p><button class="secondary small" data-go="8">Revoir mes avantages</button><div class="ref">Livre de base, p. 188–189. Cette page décrit votre couverture ; elle ne modifie pas vos points.</div></section>`;}
function ceremonySummary(){const c=CEREMONIES.find(c=>c.id===s.ceremony);return c?`<h3>Cérémonie de Néant · ${esc(c.name)}</h3><p>${esc(c.description)}</p>`:'';}
function review(){const d=derived(s),c=CLANS[s.embrace.clan];return `<div class="review-grid"><div class="review-block"><h3>Identité</h3><p>${esc(s.identity.name||'Nom à définir')}<br>${esc(s.identity.concept)}<br>${esc(s.identity.profession)}</p><p>${c?c.name:'Clan à définir'} · ${s.embrace.generation}e génération<br>Sire : ${esc(s.embrace.sire||'À définir')}</p></div><div class="review-block"><h3>Disciplines et pouvoirs</h3>${disciplineIds(s).map(d=>`<p>${DISC[d]?.[0]} ${score(s,d)}<br>${(s.powers[d]||[]).map(id=>esc(POWERS.find(p=>p.id===id)?.name)).join(', ')}</p>`).join('')}${s.ritual?`<p>Rituel : ${esc(RITUALS.find(r=>r[0]===s.ritual)?.[1])}</p>`:''}</div><div class="review-block"><h3>Se nourrir</h3>${predatorSummary()}</div><div class="review-block"><h3>Attributs</h3>${ATTR.map(([id,n])=>`<p>${n} : ${s.attributes[id]}</p>`).join('')}</div><div class="review-block"><h3>Compétences</h3>${SKILLS.filter(([id])=>effectiveSkills(s)[id]>0).map(([id,n])=>`<p>${n} : ${effectiveSkills(s)[id]}${s.specialties[id]?' · '+esc(s.specialties[id]):''}${s.freeSpecialty.skill===id?' · '+esc(s.freeSpecialty.text):''}${predatorSpecialty(s,id)?' · '+esc(predatorSpecialty(s,id))+' (prédation)':''}</p>`).join('')}</div><div class="review-block"><h3>Avantages et handicaps</h3>${allTraits(s).map(t=>`<p>${esc(TRAITS.find(x=>x.id===t.id)?.name)} : ${t.level}${t.detail?' — '+esc(t.detail):''}${t.source?' · '+(t.source==='predation'?'prédation':'base + prédation'):''}</p>`).join('')}${c?`<p>Fléau : ${c.bane}</p>`:''}</div><div class="review-block"><h3>Liens et objectifs</h3>${s.connections.map(x=>`<p>${esc(x.conviction)}<br>Attache : ${esc(x.name)} · ${esc(x.relation)}</p>`).join('')}<p>Ambition : ${esc(s.ambition)}<br>Désir : ${esc(s.desire)}</p></div>${maskSummary()}${ceremonySummary()}</div>`;}
function finalNav(){return `<nav class="final-nav" aria-label="Préparer le dossier final">${['Vérifier','Créer le PDF'].map((label,i)=>`<button class="secondary ${finalStep===i?'selected':''}" data-final-step="${i}" ${finalStep===i?'aria-current="step"':''}>${i+1}. ${label}</button>`).join('')}</nav>`;}
function createPanel(){const art=s.artwork;return `<section class="stage artwork-stage"><h2>Créer votre PDF avec votre IA</h2><p class="muted">Le prompt contient votre personnage et les consignes du dossier : composition A4, humain étonné face à son reflet vampirique, illustration en fond à 20 % d’opacité.</p><ol class="flow-instructions"><li><b>Récupérez le prompt du dossier</b><div class="help-row"><button class="primary" data-art-prompt="document">Récupérer le prompt du PDF</button></div></li><li><b>Dans votre IA, collez le prompt et joignez votre portrait déjà créé.</b><p class="muted">Utilisez par exemple une conversation avec une IA capable de créer des images et des PDF. Ajoutez le fichier de votre portrait directement à cette conversation. Vous n’avez pas à l’importer sur ce site.</p></li><li><b>Lancez la génération et téléchargez le PDF fourni par l’IA.</b><p class="muted">Votre dossier illustré est terminé. Vous pouvez conserver votre progression ici en sauvegardant le JSON.</p></li></ol><button class="secondary small" data-action="export">Sauvegarder mon personnage en JSON</button><div class="flow-actions"><button class="inline-btn" data-final-step="0">← Vérifier mon personnage</button></div></section><details class="stage alternative-route"><summary>Autre méthode : fabriquer le PDF directement sur ce site</summary><div class="detail-body"><p class="muted">Cette méthode utilise la mise en page du site. Vous pouvez télécharger le dossier immédiatement, ou lui ajouter une illustration.</p><ol class="flow-instructions"><li>Pour créer le fond, récupérez le prompt d’illustration et transmettez-le à votre IA avec votre portrait.<div class="help-row"><button class="secondary small" data-art-prompt="image">Récupérer le prompt d’illustration</button></div></li><li>Importez l’illustration A4 obtenue.<label class="art-upload">Choisir mon illustration<input type="file" accept="image/jpeg,image/png,image/webp" data-art-upload="background"></label>${art.background?`<div class="art-preview"><img src="${esc(art.background)}" alt="Illustration personnalisée pour le PDF"><div><p class="muted">${esc(art.backgroundName)}</p><p class="hint">Fond appliqué à 20 % d’opacité.</p><button class="remove" data-action="remove-background">Retirer l’illustration</button></div></div>`:'<p class="hint">Illustration facultative : sans elle, le PDF garde son papier ivoire.</p>'}</li><li>Téléchargez le dossier mis en page par le site.<div class="help-row"><button class="primary" data-action="download-dossier" ${dossierBusy?'disabled aria-busy="true"':''}>${dossierBusy?'Préparation du dossier…':'Télécharger le dossier PDF'}</button></div></li></ol></div></details>`;}
let artworkRequest={portrait:0,background:0};
async function importArtwork(file,key){if(!file||key!=='background')return;const state=s,request=++artworkRequest[key];try{if(file.size>10*1024*1024)throw Error('Image trop volumineuse : maximum 10 Mo.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choisissez une image JPEG, PNG ou WebP.');const url=URL.createObjectURL(file);let img;try{img=await new Promise((resolve,reject)=>{const item=new Image();item.onload=()=>resolve(item);item.onerror=()=>reject(Error('Cette image ne peut pas être lue.'));item.src=url;});}finally{URL.revokeObjectURL(url);}if(img.naturalWidth*img.naturalHeight>45000000)throw Error('Cette image est trop grande. Réduisez-la avant de l’importer.');const canvas=document.createElement('canvas');let edge=1600,data;do{const scale=Math.min(1,edge/Math.max(img.naturalWidth,img.naturalHeight));canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#f8f3e8';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);data=canvas.toDataURL('image/jpeg',.88);edge=Math.floor(edge*.8);}while(data.length>1300000&&edge>400);if(!isArtworkData(data))throw Error('Cette image ne peut pas être enregistrée.');if(s!==state||request!==artworkRequest[key])return;state.artwork[key]=data;state.artwork[key+'Name']=file.name.slice(0,180);save();render();toast(storageOK?'Image ajoutée au dossier.':'Image ajoutée. Exportez le JSON : le stockage de cet appareil est plein.');}catch(error){if(s===state&&request===artworkRequest[key])toast(error.message||'Import de l’image impossible.');}}
function promptText(kind){return illustrationPrompt({...s,promptSummary:{clan:CLANS[s.embrace.clan],guideDuClan:CLAN_GUIDE[s.embrace.clan],pouvoirsChoisis:disciplineIds(s).flatMap(d=>(s.powers[d]||[]).map(id=>POWERS.find(p=>p.id===id)).filter(Boolean)),ceremonie:CEREMONIES.find(c=>c.id===s.ceremony),valeursFinales:derived(s),competencesFinales:effectiveSkills(s),avantagesEtHandicaps:allTraits(s),pointsARevoir:errors(s).flat()}},{document:kind==='document'});}
function promptDialog(kind){showModal(`<h2 id="modal-title">${kind==='document'?'Créer votre dossier PDF illustré':'Créer votre illustration A4'}</h2><p>Copiez ce prompt et joignez le portrait de <b>${esc(s.identity.name||'votre personnage')}</b> à l’IA. Le portrait reste une pièce jointe distincte.</p><div class="field"><label for="art-prompt-text">Prompt personnalisé</label><textarea id="art-prompt-text" readonly rows="13">${esc(promptText(kind))}</textarea></div><div class="modal-actions"><button class="primary" data-action="copy-art-prompt">Copier le prompt</button></div><p id="prompt-copy-status" role="status" class="hint"></p>`);}
async function copyArtPrompt(){const area=$('#art-prompt-text');try{await navigator.clipboard.writeText(area.value);$('#prompt-copy-status').textContent='Prompt copié. Joignez maintenant le portrait dans votre conversation avec l’IA.';}catch{area.focus();area.select();$('#prompt-copy-status').textContent='Copie automatique indisponible : le texte est sélectionné. Utilisez Ctrl+C ou Cmd+C.';}}
function p9(){const ee=errors(s),total=ee.flat().length,d=derived(s);const nav=finalNav();if(finalStep===1)return nav+createPanel();return `${nav}<section class="stage"><div class="eyebrow">Dossier ${total?'en cours':'vérifié'}</div><h2>${esc(s.identity.name||'Votre personnage')}</h2><p class="muted">${esc(s.identity.concept)}</p><div class="summary-stats">${[[d.health,'Santé maximale'],[d.willpower,'Volonté maximale'],[d.humanity,'Humanité'],[d.bloodPotency,'Puissance du sang']].map(([n,label])=>`<div class="summary-stat"><b>${n}</b><small>${label}</small></div>`).join('')}</div>${total?`<div class="errors"><strong>${total} élément(s) restent à préciser. Vous pouvez créer un dossier portant la mention Brouillon.</strong></div><details><summary>Voir les points à compléter</summary>${STEPS.slice(0,-1).map((x,i)=>ee[i].length?`<div class="review-block"><h3>${x[0]}</h3><ul class="muted">${ee[i].map(text=>`<li>${esc(text)}</li>`).join('')}</ul><button class="inline-btn" data-go="${i}">Corriger cette étape →</button></div>`:'').join('')}</details>`:'<div class="note good">Les vérifications automatiques sont satisfaites. Validez votre personnage avec le conteur.</div>'}<details class="review-details"><summary>Relire mon personnage complet</summary>${review()}</details><div class="flow-actions"><button class="secondary" data-action="export">Sauvegarder le JSON</button><button class="primary" data-final-step="1">Préparer mon PDF →</button></div><details class="alternative-route"><summary>Télécharger ou imprimer depuis ce site</summary><div class="help-row"><button class="secondary small" data-action="download-dossier" ${dossierBusy?'disabled':''}>Télécharger le dossier PDF</button><button class="secondary small" data-action="print">Imprimer le récapitulatif</button></div><p class="hint">Le PDF utilise l’illustration déjà importée si votre dossier en contient une.</p></details></section>`;}
function go(n){s.step=Math.max(0,Math.min(STEPS.length-1,n));if(!s.visited.includes(s.step))s.visited.push(s.step);save();render();window.scrollTo({top:0,behavior:'instant'});$('#page-title')?.focus({preventScroll:true});const item=$('.navitem.active');item?.scrollIntoView({block:'nearest',inline:'center'});}
function exportJSON(){save();const blob=new Blob([JSON.stringify({...s,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(s.identity.name||'mon-vampire').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'-').toLowerCase()+'-v5.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);toast('Votre sauvegarde JSON a été téléchargée.');}
async function readFile(file){if(!file)return;if(file.size>8*1024*1024){toast('Fichier trop volumineux : maximum 8 Mo.');return;}try{const result=importJSON(JSON.parse(await file.text()));pending=result;showModal(`<div class="eyebrow">Aperçu avant import</div><h2 id="modal-title">${result.native?'Reprendre une sauvegarde':'Retrouver le background'}</h2><p>Personnage : <b>${esc(result.state.identity.name||'Nom non reconnu')}</b></p><p>${result.native?'Les choix de création seront restaurés.':`${result.mapped.length} champ(s) reconnu(s). Le document original sera conservé intégralement dans la sauvegarde, y compris les champs non reconnus.`}</p><ul>${result.mapped.map(k=>`<li>${esc(({name:'Nom',concept:'Concept',profession:'Profession',birth:'Naissance',age:'Âge',appearance:'Apparence',history:'Histoire',possessions:'Possessions',notes:'Notes'})[k]||k)}</li>`).join('')}</ul><div class="note warn">Charger ce fichier remplacera le personnage actuellement ouvert sur cet appareil. Téléchargez sa sauvegarde si vous souhaitez le conserver.</div><div class="modal-actions"><button class="secondary" data-action="export">Sauvegarder le personnage actuel</button><button class="primary" data-action="apply-import">Charger ce dossier</button></div>`);}catch(e){toast('Import impossible : '+(e instanceof SyntaxError?'le fichier ne contient pas un JSON valide.':e.message));}}
async function downloadDossier(button){if(dossierBusy)return;dossierBusy=true;save();const snapshot=JSON.parse(JSON.stringify(s));button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='Préparation du dossier…';try{const {createDownloadableDossier}=await import('./dossier-pdf.js');const result=await createDownloadableDossier(snapshot);const url=URL.createObjectURL(new Blob([result.bytes],{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download=result.filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Votre dossier PDF a été téléchargé.');}catch(error){toast('Téléchargement impossible : '+(error.message||'réessayez dans un instant.'));}finally{dossierBusy=false;for(const control of new Set([button,document.querySelector('[data-action="download-dossier"]')].filter(Boolean))){control.disabled=false;control.removeAttribute('aria-busy');control.textContent='Télécharger le dossier PDF';}}}
function printSheet(){const d=derived(s),c=CLANS[s.embrace.clan],ee=errors(s).flat();const row=(a,b)=>`<div class="printrow"><span>${esc(a)}</span><b>${esc(b)}</b></div>`;$('#print-sheet').innerHTML=`<section class="printpage"><h1>Vampire : La Mascarade</h1><p class="printsmall">CHICAGO 1940 · FICHE DE CRÉATION · V5 · BASE ET GUIDE DU JOUEUR</p>${ee.length?`<p class="printwarning">BROUILLON — ${ee.length} élément(s) restent à compléter ou valider.</p>`:''}<div class="printpair"><div>${row('Nom',s.identity.name)}${row('Concept',s.identity.concept)}${row('Clan',c?.name||'À définir')}${row('Sire',s.embrace.sire)}</div><div>${row('Chronique','Chicago 1940')}${row('Génération',s.embrace.generation+'e')}${row('Ambition',s.ambition)}${row('Désir',s.desire)}</div></div><h2>Attributs</h2><div class="printcols">${['Physique','Social','Mental'].map(g=>`<div><h3>${g}</h3>${ATTR.filter(a=>a[2]===g).map(([id,n])=>row(n,'●'.repeat(s.attributes[id])+'○'.repeat(5-s.attributes[id]))).join('')}</div>`).join('')}</div><p><span class="printbadge">Santé : ${d.health} □□□□□ □□□□□</span><span class="printbadge">Volonté : ${d.willpower} □□□□□ □□□□□</span></p><h2>Compétences et spécialités</h2><div class="printcols">${['Physique','Social','Mental'].map(g=>`<div><h3>${g}</h3>${SKILLS.filter(a=>a[2]===g).map(([id,n])=>`${row(n,effectiveSkills(s)[id])}${s.specialties[id]?'<p class="printsmall">'+esc(s.specialties[id])+'</p>':''}${s.freeSpecialty.skill===id?'<p class="printsmall">'+esc(s.freeSpecialty.text)+'</p>':''}${predatorSpecialty(s,id)?'<p class="printsmall">'+esc(predatorSpecialty(s,id))+' (prédation)</p>':''}`).join('')}</div>`).join('')}</div><h2>Disciplines</h2>${disciplineIds(s).map(id=>`<p><b>${DISC[id]?.[0]} ${score(s,id)}</b> · ${(s.powers[id]||[]).map(p=>esc(POWERS.find(x=>x.id===p)?.name)).join(' ; ')}</p>`).join('')}<p>${s.ritual?'Rituel : '+esc(RITUALS.find(x=>x[0]===s.ritual)?.[1]):''}</p><p><span class="printbadge">Humanité : ${d.humanity} / 10</span><span class="printbadge">Soif : □□□□□</span><span class="printbadge">Résonance : __________</span></p></section><section class="printpage"><h1>Liens, moyens & histoire</h1><h2>Principes de la chronique</h2><p>${esc(s.principles||'À définir avec le groupe.')}</p><h2>Convictions et Attaches</h2>${s.connections.map(x=>`<div class="printblock"><p><b>${esc(x.conviction)}</b><br>${esc(x.name)} · ${esc(x.relation)}</p></div>`).join('')}<h2>Avantages et handicaps</h2>${allTraits(s).map(x=>`<div class="printblock"><p><b>${esc(TRAITS.find(t=>t.id===x.id)?.name)} ${x.level}</b>${x.detail?' — '+esc(x.detail):''}${x.source?' · '+(x.source==='predation'?'prédation':'base + prédation'):''}</p></div>`).join('')}${s.embrace.clan==='nosferatu'?'<p>Repoussant : imposé par le fléau, sans points de handicap.</p>':''}<h2>Le sang</h2><p>Puissance du sang : ${d.bloodPotency} · Coup de sang : +1 dé · Régénération : ${d.bloodPotency===2?2:1} dégât(s) superficiel(s) par Exaltation · Bonus aux pouvoirs : ${d.bloodPotency===2?"+1 dé":"aucun"} · Relance d’Exaltation : pouvoirs de discipline de niveau 1 · Score de Fléau : 1 · Pénalité alimentaire : ${d.bloodPotency===2?"deux fois plus de sang animal ou en poche nécessaire":"aucune liée à la Puissance du sang"}.</p><p><b>Fléau :</b> ${c?esc(c.bane):'À définir'}</p>${s.embrace.clanDetail?'<p>'+esc(s.embrace.clanDetail)+'</p>':''}<h2>Se nourrir</h2>${predatorSummary()}<p>Expérience totale : 0 · Expérience dépensée : 0.</p><h2>Identité et histoire</h2><p>Naissance : ${esc(s.identity.birth)} · Âge apparent : ${esc(s.identity.age)} · Étreinte : ${esc(s.embrace.date)}</p><p>${esc(s.identity.appearance)}</p><p>${esc(s.identity.history)}</p><h2>Existence nocturne et possessions</h2><p>${esc(s.night.refuge)}<br>${esc(s.night.mask)}</p><p>${esc(s.night.possessions||s.identity.possessions)}</p><p>${esc(s.identity.notes)}</p></section><section class="printpage"><h1>Vos pouvoirs, à portée de main</h1><p>Jet : attribut + compétence (ou discipline). Chaque résultat de 6 ou plus est une réussite ; deux 10 comptent pour quatre réussites. Les dés de Soif remplacent autant de dés ordinaires dans le groupement.</p><p>Test d’Exaltation : un dé, 6+ maintient la Soif ; 1–5 l’augmente d’un point. L’effet fonctionne généralement malgré l’augmentation de Soif.</p>${Object.values(s.powers).flat().map(id=>{const p=POWERS.find(x=>x.id===id);return p?`<div class="printpower"><h3>${p.name} · ${DISC[p.disc][0]} ${p.level}</h3><p>${p.effect}</p><p><b>Coût :</b> ${p.cost}<br><b>Jet :</b> ${p.roll}<br><b>Limites :</b> ${p.limit}</p><p class="printsmall">Livre de base, p. ${p.page}.</p></div>`:'';}).join('')}${s.ritual?`<h2>Rituel : ${esc(RITUALS.find(x=>x[0]===s.ritual)?.[1])}</h2><p>${esc(RITUALS.find(x=>x[0]===s.ritual)?.[2])}</p><p>Préparation et ingrédients requis. Consultez le livre de base, p. 274–276.</p>`:''}${maskSummary()}${ceremonySummary()}${ee.length?`<h2>Points restant à revoir</h2><ul>${ee.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<p class="printsmall">Assistant personnel de création. Les résumés ne remplacent pas les conditions complètes du livre. Les données originales de background restent dans la sauvegarde JSON.</p></section>`;window.print();}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.dataset.finalStep!==undefined){finalStep=Math.max(0,Math.min(1,Number(el.dataset.finalStep)||0));render();$('#page-title')?.focus({preventScroll:true});$('.final-nav')?.scrollIntoView({block:'start'});return;}if(el.dataset.artPrompt){promptDialog(el.dataset.artPrompt);return;}if(el.dataset.expand){const area=document.getElementById(el.dataset.expand);if(area){const expanded=el.getAttribute('aria-expanded')!=='true';area.classList.toggle('expanded',expanded);el.setAttribute('aria-expanded',String(expanded));el.textContent=expanded?'Réduire le champ':'Agrandir le champ';area.focus({preventScroll:true});}return;}if(el.dataset.powerTab!==undefined){powerTab=Number(el.dataset.powerTab);render();return;}if(el.dataset.help){helpModal(el.dataset.help);return;}if(el.dataset.go!==undefined){go(Number(el.dataset.go));return;}if(el.dataset.attr){set('attributes.'+el.dataset.attr,Number(el.dataset.value));render();return;}if(el.dataset.tab){tab=el.dataset.tab;render();return;}if(el.dataset.profile){const id=el.dataset.profile;if(id===s.profile)return;if(Object.values(s.skills).some(Boolean)){showModal(`<h2 id="modal-title">Changer de répartition ?</h2><p>Les compétences et leurs spécialités seront remises à zéro. Votre histoire et les autres choix sont conservés.</p><div class="modal-actions"><button class="secondary" data-action="close">Annuler</button><button class="primary" data-confirm-profile="${id}">Changer et répartir à nouveau</button></div>`);}else{s.profile=id;save();render();}return;}if(el.dataset.confirmProfile){s.profile=el.dataset.confirmProfile;s.skills=blank().skills;s.specialties={};s.freeSpecialty={skill:'',text:''};$('#modal').close();save();render();return;}if(el.dataset.clan){requestClanChange(el.dataset.clan);return;}if(el.dataset.confirmClan){$('#modal').close();applyClan(el.dataset.confirmClan);return;}if(el.dataset.disc&&el.dataset.slot){const d=el.dataset.disc,k=el.dataset.slot,other=k==='major'?'minor':'major';s.disciplines[k]=d;if(s.disciplines[other]===d)s.disciplines[other]='';normalizePowers(s);save();render();return;}if(el.dataset.traitPage!==undefined){traitPage=Number(el.dataset.traitPage);render();return;}if(el.dataset.traitTab){traitPage=0;traitTab=el.dataset.traitTab;render();return;}if(el.dataset.traitType){traitPage=0;traitType=el.dataset.traitType;render();return;}if(el.dataset.add){const t=TRAITS.find(t=>t.id===el.dataset.add),issue=traitIssue(s,t);if(issue){toast(issue);return;}const efficacy=t.allies?Number($('#eff-'+t.id).value):0,reliability=t.allies?Number($('#fiab-'+t.id).value):0,level=t.allies?efficacy+reliability:Number($('#level-'+t.id).value);if(!t.levels.includes(level)){toast('Choisissez une valeur valide.');return;}if(t.type==='a'&&budget(s,'a')+level>7){toast('Ce choix dépasse les 7 points d’avantages.');return;}s.traits.push({id:t.id,level,detail:'',efficacy,reliability});save();render();return;}if(el.dataset.remove!==undefined){s.traits.splice(Number(el.dataset.remove),1);save();render();return;}if(el.dataset.removePair!==undefined){s.connections.splice(Number(el.dataset.removePair),1);save();render();return;}const action=el.dataset.action;if(action==='copy-art-prompt'){copyArtPrompt();return;}if(action==='remove-background'){artworkRequest.background++;s.artwork.background='';s.artwork.backgroundName='';save();render();return;}if(action==='next'){const n=errors(s)[s.step].length;if(n)toast(`${n} élément(s) restent à compléter sur cette étape. Votre brouillon est conservé.`);go(s.step+1);}if(action==='prev')go(s.step-1);if(action==='export')exportJSON();if(action==='import')$('#import-file').click();if(action==='close')$('#modal').close();if(action==='apply-import'&&pending){s=pending.state;pending=null;$('#modal').close();save();render();go(s.step);toast('Dossier chargé. Vérifiez les champs reconnus.');}if(action==='pair'){s.connections.push({conviction:'',name:'',relation:''});save();render();}if(action==='print')printSheet();if(action==='download-dossier')downloadDossier(el);if(action==='original'){showModal(`<h2 id="modal-title">Le dossier humain original</h2><p>Ces informations sont conservées dans votre JSON. Complétez les champs de la fiche si certains n’ont pas été reconnus.</p><pre class="raw">${esc(JSON.stringify(s.originalBackground,null,2))}</pre>`);}if(action==='guide'){showModal(`<div class="eyebrow">Les premières nuits</div><h2 id="modal-title">Une étape à la fois</h2><p>Choisissez vos caractéristiques à partir du personnage que vous avez imaginé. Les boutons « i » expliquent chaque notion ; vous pouvez revenir sur vos choix et naviguer librement dans les douze étapes.</p><p>Une étape incomplète reste un brouillon. La dernière page rassemble les points à corriger avant validation avec le conteur.</p>`);}if(action==='reset')showModal(`<h2 id="modal-title">Commencer un autre personnage ?</h2><p>Le personnage ouvert sera remplacé sur cet appareil. Vous pouvez d’abord télécharger sa sauvegarde.</p><div class="modal-actions"><button class="secondary" data-action="export">Sauvegarder l’actuel</button><button class="primary" data-action="confirm-reset">Commencer un nouveau dossier</button></div>`);if(action==='confirm-reset'){s=blank();$('#modal').close();save();go(0);}});
function requestClanChange(id){if(id===s.embrace.clan)return;if(s.disciplines.major||s.disciplines.minor){showModal(`<h2 id="modal-title">Changer de clan ?</h2><p>Les disciplines, les pouvoirs et le rituel seront remis à zéro. Les avantages seront conservés et leurs incompatibilités éventuelles signalées.</p><div class="modal-actions"><button class="secondary" data-action="close">Annuler</button><button class="primary" data-confirm-clan="${id}">Confirmer le changement</button></div>`);}else{applyClan(id);}}
function applyClan(id){s.embrace.clan=id;s.embrace.confirmed=false;s.embrace.clanDetail='';s.disciplines={major:'',minor:''};s.powers={};s.ritual='';s.ceremony='';save();render();}
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.field){let val=el.type==='checkbox'?el.checked:el.value;if(['embrace.generation','embrace.humanity','predator.fame'].includes(el.dataset.field))val=Number(val);set(el.dataset.field,val);if(el.dataset.field.startsWith('predator.')&&$('#predator-status')){const ee=predatorErrors(s);$('#predator-status').textContent=ee.length?'À compléter : '+ee.join(' '):'Les effets sont intégrés à votre fiche. Confirmez ce choix avec le conteur.';}}if(el.dataset.traitDetail!==undefined){s.traits[Number(el.dataset.traitDetail)].detail=el.value;save();}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.traitLevel){refreshTraitLevel(el.dataset.traitLevel);return;}if(el.dataset.artUpload){importArtwork(el.files?.[0],el.dataset.artUpload);el.value='';return;}if(el.dataset.osirisFlaw!==undefined){const i=Number(el.dataset.osirisFlaw),[id,level]=el.value.split(':');while(s.predator.osirisFlaws.length<=i)s.predator.osirisFlaws.push({id:'',level:0,detail:''});s.predator.osirisFlaws[i]={id,level:Number(level)||0,detail:''};save();render();return;}if(el.dataset.clanSelect!==undefined){requestClanChange(el.value);return;}if(el.dataset.field&&el.tagName==='SELECT'){const path=el.dataset.field;let val=['embrace.generation','embrace.humanity','predator.fame'].includes(path)?Number(el.value):el.value;set(path,val);if(path.startsWith('predator.')){if(path==='predator.style'){const mode=s.predator.mode,style=val;s.predator={...predatorDefault(),mode,style};}normalizePowers(s);powerTab=0;save();render();}else if(path==='freeSpecialty.skill')render();}if(el.dataset.skill){const id=el.dataset.skill,value=Number(el.value),target=PROFILES[s.profile].slots.filter(n=>n===value).length,used=Object.entries(s.skills).filter(([k,n])=>k!==id&&n===value).length;if(value>0&&used>=target){toast('Aucun emplacement à '+value+' points disponible. Libérez une compétence ou choisissez un autre score.');render();return;}if(s.traits.some(x=>x.id==='illettre')&&['erudition','sciences'].includes(id)&&value>1){toast('Illettré limite cette compétence à 1.');render();return;}s.skills[id]=value;if(!s.skills[el.dataset.skill]){delete s.specialties[el.dataset.skill];if(s.freeSpecialty.skill===el.dataset.skill)s.freeSpecialty={skill:'',text:''};}save();render();}if(el.dataset.power){const p=POWERS.find(x=>x.id===el.dataset.power);if(!powerAllowed(s,p))return;const d=el.dataset.disc,slot=Number(el.dataset.slot);s.powers[d]||=[];s.powers[d][slot]=p.id;normalizePowers(s);save();render();}if(el.dataset.ritual){s.ritual=el.dataset.ritual;save();render();}});
$('#import-file').addEventListener('change',e=>{readFile(e.target.files[0]);e.target.value='';});$('#close-modal').addEventListener('click',()=>$('#modal').close());$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
document.addEventListener('dragover',e=>{if(e.target.closest('#dropzone')){e.preventDefault();$('#dropzone').classList.add('drag');}});document.addEventListener('dragleave',e=>{if(e.target.closest('#dropzone'))$('#dropzone')?.classList.remove('drag');});document.addEventListener('drop',e=>{if(e.target.closest('#dropzone')){e.preventDefault();$('#dropzone').classList.remove('drag');readFile(e.dataTransfer.files[0]);}});
window.addEventListener('beforeunload',save);render();
